  out.send_kind='menu';
  out.text='🎯 Adicionado! Escolha mais ou toque em ✅ Concluir 👇\n\n✅ Selecionados: '+summary();
  out.sql=setSql([['interests',jstr(interests)+'::jsonb'],['int_await',"'false'::jsonb"]]);
}
else if(sub==='done'){
  if(isOnb){ out.send_kind='done_onb'; out.sql="UPDATE students SET profile=jsonb_set(COALESCE(profile,'{}'::jsonb),'{int_await}','false'::jsonb), onboarding='done', updated_at=now() WHERE user_id="+uid+';'; }
  else { out.send_kind='done'; out.text='👍 Seus interesses: '+summary(); out.sql=setSql([['int_await',"'false'::jsonb"]]); }
}
else {
  out.send_kind='menu';
  out.text='🎯 Sobre o que você curte conversar? Escolha seus interesses 👇\n\n✅ Selecionados: '+summary();
  out.sql=setSql([['int_await',"'false'::jsonb"]]);
}
return { json:{ ...d, ...out } };
